  ('lner-ecml', '[{"severity":10,"reason":"Good Service","validity":{"from_date":"2026-09-16T00:00:00Z","to_date":"2026-09-17T06:00:00Z","is_now":false}}]'::jsonb, NOW() - INTERVAL '1 day');

